mkdir -p tmp/followup-R-pre && cat > tmp/followup-R-pre/fns.sh <<'EOF'
run_bg () {
    nohup bash -c "( $2 ) > '$1' 2>&1; echo EXIT=\$? >> '$1'" >/dev/null 2>&1 &
}
wait_for () {
    local n=0
    while ! grep -q '^EXIT=' "$1" 2>/dev/null ; do
        sleep 5 ; n=$((n+5))
        [ "$n" -ge "${2:-480}" ] && { echo "still running after ${n}s" ; return 1 ; }
    done
    grep -n '^BUILD \|^Total time:\|^EXIT=' "$1"
}
EOF
source explorations/experiment/env.sh && source tmp/followup-R-pre/fns.sh && echo $FORTRESS_HOME && run_bg tmp/followup-R-pre/compileAll.txt "cd $FORTRESS_HOME && ant compileAll" && sleep 2 && wait_for tmp/followup-R-pre/compileAll.txt 400

